00207 template<typename T, size_t N>
00208 uint32_t updateCandList(T uiMode, double uiCost, static_vector<T, N>& candModeList, static_vector<double, N>& candCostList
00209   , size_t uiFastCandNum = N, int* iserttPos = nullptr)
00210 {
00211   CHECK( std::min( uiFastCandNum, candModeList.size() ) != std::min( uiFastCandNum, candCostList.size() ), "Sizes do not match!" );
00212   CHECK( uiFastCandNum > candModeList.capacity(), "The vector is to small to hold all the candidates!" );
00213 
00214   size_t i;
00215   size_t shift = 0;
00216   size_t currSize = std::min( uiFastCandNum, candCostList.size() );
00217 
00218   while( shift < uiFastCandNum && shift < currSize && uiCost < candCostList[currSize - 1 - shift] )
00219   {
00220     shift++;
00221   }
00222 
00223   if( candModeList.size() >= uiFastCandNum && shift != 0 )
00224   {
00225     for( i = 1; i < shift; i++ )
00226     {
00227       candModeList[currSize - i] = candModeList[currSize - 1 - i];
00228       candCostList[currSize - i] = candCostList[currSize - 1 - i];
00229     }
00230     candModeList[currSize - shift] = uiMode;
00231     candCostList[currSize - shift] = uiCost;
00232     if (iserttPos != nullptr)
00233     {
00234       *iserttPos = int(currSize - shift);
00235     }
00236     return 1;
00237   }
00238   else if( currSize < uiFastCandNum )
00239   {
00240     candModeList.insert( candModeList.end() - shift, uiMode );
00241     candCostList.insert( candCostList.end() - shift, uiCost );
00242     if (iserttPos != nullptr)
00243     {
00244       *iserttPos = int(candModeList.size() - shift - 1);
00245     }
00246     return 1;
00247   }
00248   if (iserttPos != nullptr)
00249   {
00250     *iserttPos = -1;
00251   }
00252   return 0;
00253 }
